// SPDX-License-Identifier: CECILL-2.1
// PERMANOVA / PERMDISP: hand-derived closed forms plus the reference gate
// parity/fixtures/permanova_v1.json, generated by
// parity/generators/permanova_v1.py (NumPy 2.2.6 lstsq on full one-hot
// designs, SciPy 1.15.3 f_oneway, scikit-bio 0.7.4 permanova/permdisp, and
// NumPy default_rng permutation counts). Test-only references.
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

#include "fixture_parser.hpp"
#include "n4m/n4m.h"

#define REQUIRE(x) do { if (!(x)) throw std::runtime_error(std::string(#x) + " @" + std::to_string(__LINE__)); } while (false)

namespace {
using namespace n4m_testing;

struct Permanova {
    double v[13];
    int64_t counts[2];
};

n4m_matrix_view_t view(double* x, int64_t n, int64_t k) {
    n4m_matrix_view_t v{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&v, x, n, k, N4M_DTYPE_F64) == N4M_OK);
    return v;
}

n4m_status_t permanova(n4m_context_t* ctx, const n4m_matrix_view_t& X, const int64_t* term,
                       const int64_t* strata, int32_t b, uint64_t seed, Permanova& out) {
    return n4m_stats_permanova(ctx, &X, term, strata, b, seed, out.v, out.counts);
}

bool near(double got, double want, double scale = 1.0) {
    if (std::isnan(want)) return std::isnan(got);
    return std::abs(got - want) <= 1e-10 * std::max(scale, std::abs(want));
}

std::pair<size_t, size_t> object_span(const std::string& s, const std::string& key,
                                      size_t lo, size_t hi) {
    const auto [b, e] = read_value_span(s, find_value_for_key(s, key, lo, hi));
    return {b, e};
}

double hex_scalar(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    return hex_to_double(s, find_value_for_key(s, key, lo, hi));
}

std::vector<double> hex_list(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    std::vector<double> out;
    parse_hex_double_array(s, pos, out);
    return out;
}

std::vector<int64_t> int_list(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    std::vector<int64_t> out;
    if (s[pos] == 'n') return out;  // null
    REQUIRE(s[pos] == '[');
    ++pos;
    while (true) {
        skip_ws(s, pos);
        if (s[pos] == ']') break;
        char* tail = nullptr;
        out.push_back(std::strtoll(s.c_str() + pos, &tail, 10));
        pos = static_cast<size_t>(tail - s.c_str());
        skip_ws(s, pos);
        if (s[pos] == ',') ++pos;
    }
    return out;
}

int64_t integer(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    return parse_int64(s, find_value_for_key(s, key, lo, hi));
}

void gate_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    size_t name_pos = find_value_for_key(s, "name", lo, hi);
    const auto name = parse_string(s, name_pos);
    const int64_t rows = integer(s, "rows", lo, hi), cols = integer(s, "cols", lo, hi);
    auto x = hex_list(s, "X", lo, hi);
    REQUIRE(static_cast<int64_t>(x.size()) == rows * cols);
    const auto term = int_list(s, "term", lo, hi);
    const auto strata = int_list(s, "strata", lo, hi);
    const auto seed = static_cast<uint64_t>(integer(s, "seed", lo, hi));
    const auto b = static_cast<int32_t>(integer(s, "n_permutations", lo, hi));
    const auto X = view(x.data(), rows, cols);
    Permanova got{};
    REQUIRE(permanova(ctx, X, term.data(), strata.empty() ? nullptr : strata.data(), b, seed, got)
            == N4M_OK);
    const auto [plo, phi] = object_span(s, "permanova", lo, hi);
    const double total = hex_scalar(s, "ss_total", plo, phi);
    const char* keys[] = {"ss_total", "ss_strata", "ss_term", "ss_residual", "r2", "partial_r2",
                          "pseudo_f"};
    for (int i = 0; i < 7; ++i)
        REQUIRE(near(got.v[i], hex_scalar(s, keys[i], plo, phi), i < 4 ? total : 1.0));
    REQUIRE(got.v[7] == static_cast<double>(integer(s, "df_term", plo, phi)));
    REQUIRE(got.v[8] == static_cast<double>(integer(s, "df_residual", plo, phi)));
    REQUIRE(got.v[9] == static_cast<double>(integer(s, "n_levels", plo, phi)));
    REQUIRE(got.v[10] == static_cast<double>(integer(s, "n_strata", plo, phi)));
    REQUIRE(near(got.v[11], hex_scalar(s, "log10_distinct", plo, phi)));
    const int64_t want_b = integer(s, "b", plo, phi), executed = integer(s, "executed", plo, phi);
    REQUIRE(got.counts[0] == want_b && got.counts[1] == executed);
    REQUIRE(executed == 0 ? std::isnan(got.v[12])
                          : near(got.v[12], static_cast<double>(1 + want_b) /
                                                static_cast<double>(1 + executed)));
    // Column-major storage of the same coordinates gives identical results.
    std::vector<double> colmajor(x.size());
    for (int64_t i = 0; i < rows; ++i)
        for (int64_t j = 0; j < cols; ++j)
            colmajor[static_cast<size_t>(j * rows + i)] = x[static_cast<size_t>(i * cols + j)];
    n4m_matrix_view_t C{};
    REQUIRE(n4m_matrix_view_init_colmajor(&C, colmajor.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    Permanova again{};
    REQUIRE(permanova(ctx, C, term.data(), strata.empty() ? nullptr : strata.data(), b, seed, again)
            == N4M_OK);
    REQUIRE(again.counts[0] == got.counts[0] && again.v[2] == got.v[2]);

    if (s.find("\"permdisp\"", lo) < hi) {
        const auto [dlo, dhi] = object_span(s, "permdisp", lo, hi);
        const auto n = static_cast<size_t>(rows);
        std::vector<double> dist(n), means(n), out(6);
        int64_t counts[2] = {};
        const auto dseed = static_cast<uint64_t>(integer(s, "seed", dlo, dhi));
        REQUIRE(n4m_stats_permdisp(ctx, &X, term.data(), b, dseed, dist.data(), means.data(),
                                   out.data(), counts) == N4M_OK);
        const auto want_dist = hex_list(s, "distances", dlo, dhi);
        const auto want_means = hex_list(s, "group_mean_distances", dlo, dhi);
        for (size_t i = 0; i < n; ++i) REQUIRE(near(dist[i], want_dist[i]));
        for (size_t g = 0; g < want_means.size(); ++g) REQUIRE(near(means[g], want_means[g]));
        REQUIRE(near(out[0], hex_scalar(s, "f", dlo, dhi)));
        REQUIRE(out[1] == static_cast<double>(integer(s, "df1", dlo, dhi)));
        REQUIRE(out[2] == static_cast<double>(integer(s, "df2", dlo, dhi)));
        REQUIRE(out[3] == static_cast<double>(integer(s, "n_groups", dlo, dhi)));
        REQUIRE(near(out[4], hex_scalar(s, "log10_distinct", dlo, dhi)));
        const int64_t disp_b = integer(s, "b", dlo, dhi);
        REQUIRE(counts[0] == disp_b && counts[1] == b);
        REQUIRE(near(out[5], static_cast<double>(1 + disp_b) / static_cast<double>(1 + b)));
    }
    std::printf("permanova gate %-32s b=%lld ok\n", name.c_str(),
                static_cast<long long>(got.counts[0]));
}
}  // namespace

int main() {
    n4m_context_t* ctx = nullptr;
    try {
        REQUIRE(n4m_context_create(&ctx) == N4M_OK);
        // One factor in 1-D is one-way ANOVA. Groups {1,2,3},{7,8,9}:
        // SST=58, SS_term=54, R^2=27/29, F=54 on (1,4), 6!/(3!3!)=20.
        // Free permutation follows the n4m_preflight_factor_association
        // convention, so b for seed 17 equals its NumPy golden (93).
        double y[6] = {1, 2, 3, 7, 8, 9};
        int64_t fa[6] = {4, 4, 4, -9, -9, -9};
        auto Y = view(y, 6, 1);
        Permanova r{};
        REQUIRE(permanova(ctx, Y, fa, nullptr, 999, 17, r) == N4M_OK);
        REQUIRE(near(r.v[0], 58) && near(r.v[1], 0) && near(r.v[2], 54) && near(r.v[3], 4));
        REQUIRE(near(r.v[4], 27.0 / 29.0) && near(r.v[5], 27.0 / 29.0) && near(r.v[6], 54));
        REQUIRE(r.v[7] == 1 && r.v[8] == 4 && r.v[9] == 2 && r.v[10] == 1);
        REQUIRE(near(r.v[11], std::log10(20.0)));
        REQUIRE(r.counts[0] == 93 && r.counts[1] == 999 && near(r.v[12], 94.0 / 1000.0));
        REQUIRE(permanova(ctx, Y, fa, nullptr, 0, 17, r) == N4M_OK);
        REQUIRE(std::isnan(r.v[12]) && r.counts[1] == 0);
        // Extreme magnitudes are scaled before sums: R^2 stays 27/29.
        double yh[6] = {1e150, 2e150, 3e150, 7e150, 8e150, 9e150};
        auto YH = view(yh, 6, 1);
        REQUIRE(permanova(ctx, YH, fa, nullptr, 0, 1, r) == N4M_OK);
        REQUIRE(near(r.v[4], 27.0 / 29.0) && near(r.v[0], 58e300, 58e300));

        // Scale reconstruction never forms scale^2 (Astra review). Six values
        // of magnitude 1e-162: SS = 6e-324 rounds to the smallest subnormal.
        double tiny[6] = {-1e-162, -1e-162, -1e-162, 1e-162, 1e-162, 1e-162};
        int64_t halves6[6] = {0, 0, 0, 1, 1, 1};
        auto T = view(tiny, 6, 1);
        REQUIRE(permanova(ctx, T, halves6, nullptr, 0, 1, r) == N4M_OK);
        const double denorm = std::numeric_limits<double>::denorm_min();
        REQUIRE(r.v[0] == denorm && r.v[2] == denorm && r.v[3] == 0.0);
        REQUIRE(near(r.v[4], 1.0) && near(r.v[5], 1.0));
        // 1e155 + 1e140 * {0,2,4,12,14,16}: finite SS near 2.3e282, while
        // scale^2 would overflow. Reference: exact double differences to the
        // first value (Sterbenz), summed in long double here.
        double big[6];
        const double steps[6] = {0, 2, 4, 12, 14, 16};
        for (int i = 0; i < 6; ++i) big[i] = 1e155 + 1e140 * steps[i];
        long double mean = 0.0L, m0 = 0.0L, m1 = 0.0L;
        for (int i = 0; i < 6; ++i) mean += static_cast<long double>(big[i] - big[0]) / 6.0L;
        for (int i = 0; i < 3; ++i) m0 += static_cast<long double>(big[i] - big[0]) / 3.0L;
        for (int i = 3; i < 6; ++i) m1 += static_cast<long double>(big[i] - big[0]) / 3.0L;
        long double sst = 0.0L, ssw = 0.0L;
        for (int i = 0; i < 6; ++i) {
            const long double d = static_cast<long double>(big[i] - big[0]);
            sst += (d - mean) * (d - mean);
            ssw += (d - (i < 3 ? m0 : m1)) * (d - (i < 3 ? m0 : m1));
        }
        auto B6 = view(big, 6, 1);
        REQUIRE(permanova(ctx, B6, halves6, nullptr, 0, 1, r) == N4M_OK);
        REQUIRE(std::isfinite(r.v[0]) && r.v[0] > 2e282 && r.v[0] < 2.5e282);
        REQUIRE(near(r.v[0], static_cast<double>(sst), 0.0));
        REQUIRE(near(r.v[3], static_cast<double>(ssw), 0.0));
        REQUIRE(near(r.v[2], static_cast<double>(sst - ssw), 0.0));
        double bdist[6], bmeans[6], bout[6];
        int64_t bcounts[2];
        REQUIRE(n4m_stats_permdisp(ctx, &B6, halves6, 0, 1, bdist, bmeans, bout, bcounts) == N4M_OK);
        REQUIRE(near(bdist[0], static_cast<double>(m0 - static_cast<long double>(big[0] - big[0])), 0.0));
        REQUIRE(near(bmeans[0], static_cast<double>(
            (std::abs(static_cast<long double>(big[0] - big[0]) - m0) +
             std::abs(static_cast<long double>(big[1] - big[0]) - m0) +
             std::abs(static_cast<long double>(big[2] - big[0]) - m0)) / 3.0L), 0.0));
        double tdist[6], tmeans[6];
        REQUIRE(n4m_stats_permdisp(ctx, &T, halves6, 0, 1, tdist, tmeans, bout, bcounts) == N4M_OK);
        REQUIRE(tdist[0] == 0.0 && tmeans[1] == 0.0);

        // Balanced 2x2 in 1-D: term a1 {1,3,2,4}, a2 {5,7,6,8}; strata b1
        // {1,3,5,7}, b2 {2,4,6,8}. Orthogonal: SS_term = 32, SS_strata = 2,
        // SST = 42, SS_res = 8 on 8-3 = 5 df, F = 32/(8/5) = 20.
        double z[8] = {1, 3, 5, 7, 2, 4, 6, 8};
        int64_t ta[8] = {0, 0, 1, 1, 0, 0, 1, 1}, sb[8] = {0, 0, 0, 0, 1, 1, 1, 1};
        auto Z = view(z, 8, 1);
        REQUIRE(permanova(ctx, Z, ta, sb, 0, 1, r) == N4M_OK);
        REQUIRE(near(r.v[0], 42) && near(r.v[1], 2) && near(r.v[2], 32) && near(r.v[3], 8));
        REQUIRE(near(r.v[6], 20) && r.v[7] == 1 && r.v[8] == 5 && r.v[10] == 2);
        REQUIRE(near(r.v[5], 0.8) && near(r.v[4], 32.0 / 42.0));
        // Within strata 4!/(2!2!) = 6 assignments each: log10 36.
        REQUIRE(near(r.v[11], std::log10(36.0)));
        // Term aliased with the strata (instrument = site): df 0, no test.
        REQUIRE(permanova(ctx, Z, ta, ta, 999, 1, r) == N4M_OK);
        REQUIRE(r.v[7] == 0 && r.v[2] == 0 && std::isnan(r.v[4]) && std::isnan(r.v[6]));
        REQUIRE(r.counts[1] == 0 && std::isnan(r.v[12]) && near(r.v[11], 0));
        // Constant data: SS 0, undefined ratios, no permutation.
        double c[4] = {2, 2, 2, 2};
        int64_t tc[4] = {0, 0, 1, 1};
        auto CV = view(c, 4, 1);
        REQUIRE(permanova(ctx, CV, tc, nullptr, 99, 1, r) == N4M_OK);
        REQUIRE(near(r.v[0], 0) && std::isnan(r.v[4]) && std::isnan(r.v[5]) && r.counts[1] == 0);

        // PERMDISP hand case in 1-D: group {0,2} centroid 1 -> distances 1,1;
        // group {10,14,18} centroid 14 -> 4,0,4. Group means 1 and 8/3;
        // distance ANOVA: B = 10/3, W = 32/3, F = (10/3)/((32/3)/3) = 15/16.
        double d[5] = {0, 2, 10, 14, 18};
        int64_t gd[5] = {7, 7, 3, 3, 3};
        auto D = view(d, 5, 1);
        double dist[5], means[5], out6[6];
        int64_t counts[2];
        REQUIRE(n4m_stats_permdisp(ctx, &D, gd, 0, 1, dist, means, out6, counts) == N4M_OK);
        REQUIRE(near(dist[0], 1) && near(dist[1], 1) && near(dist[2], 4) && near(dist[3], 0) &&
                near(dist[4], 4));
        // Ascending code order: group 3 first.
        REQUIRE(near(means[0], 8.0 / 3.0) && near(means[1], 1));
        REQUIRE(near(out6[0], 15.0 / 16.0) && out6[1] == 1 && out6[2] == 3 && out6[3] == 2);
        REQUIRE(near(out6[4], std::log10(10.0)) && std::isnan(out6[5]) && counts[1] == 0);
        int64_t one_group[5] = {1, 1, 1, 1, 1};
        REQUIRE(n4m_stats_permdisp(ctx, &D, one_group, 99, 1, dist, means, out6, counts) == N4M_OK);
        REQUIRE(std::isnan(out6[0]) && std::isnan(out6[5]) && counts[1] == 0);

        // Reference gate.
        const std::string s = slurp(std::string(N4M_PARITY_FIXTURE_DIR) + "/permanova_v1.json");
        REQUIRE(s.find("\"n4m_permanova_v1\"") != std::string::npos);
        const auto [lo, hi] = find_cases_array(s);
        const auto spans = list_case_object_spans(s, lo, hi);
        REQUIRE(spans.size() == 8);
        for (const auto& [a, b] : spans) gate_case(ctx, s, a, b);

        // Argument validation.
        REQUIRE(permanova(ctx, Y, nullptr, nullptr, 0, 1, r) == N4M_ERR_NULL_POINTER);
        auto Y1 = view(y, 1, 1);
        REQUIRE(permanova(ctx, Y1, fa, nullptr, 0, 1, r) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(permanova(ctx, Y, fa, nullptr, -1, 1, r) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(permanova(ctx, Y, fa, nullptr, 1000001, 1, r) == N4M_ERR_INVALID_ARGUMENT);
        y[2] = std::nan("");
        REQUIRE(permanova(ctx, Y, fa, nullptr, 0, 1, r) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_stats_permdisp(ctx, &Y, fa, 0, 1, dist, means, out6, counts)
                == N4M_ERR_INVALID_ARGUMENT);
        y[2] = 3;
        std::vector<double> many(3000, 0.0);
        std::vector<int64_t> levels(3000);
        for (size_t i = 0; i < levels.size(); ++i) levels[i] = static_cast<int64_t>(i);
        auto M = view(many.data(), 3000, 1);
        REQUIRE(permanova(ctx, M, levels.data(), nullptr, 0, 1, r) == N4M_ERR_UNSUPPORTED);
        std::vector<double> wide(200000, 1.0);
        std::vector<int64_t> halves(100000);
        for (size_t i = 0; i < halves.size(); ++i) halves[i] = static_cast<int64_t>(i % 2);
        auto W = view(wide.data(), 100000, 2);
        REQUIRE(permanova(ctx, W, halves.data(), nullptr, 999, 1, r) == N4M_ERR_UNSUPPORTED);
        std::vector<double> wdist(100000), wmeans(100000);
        REQUIRE(n4m_stats_permdisp(ctx, &W, halves.data(), 9999, 1, wdist.data(), wmeans.data(),
                                   out6, counts) == N4M_ERR_UNSUPPORTED);
        REQUIRE(n4m_stats_permdisp(ctx, &Y, fa, 0, 1, nullptr, means, out6, counts)
                == N4M_ERR_NULL_POINTER);
        n4m_context_destroy(ctx);
        std::puts("permanova tests ok");
        return 0;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "FAILED: %s\n", e.what());
        if (ctx) n4m_context_destroy(ctx);
        return 1;
    }
}
